def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Color the trailing background of a foreground row with 1 when its
    # foreground reaches at least halfway across the row.
    vals = {v for row in grid for v in row}
    bg = max(vals, key=lambda v: sum(r.count(v) for r in grid))
    for r, row in enumerate(grid):
        nz = [c for c, v in enumerate(row) if v != bg]
        if nz and nz[-1] < w - 1 and nz[-1] >= w // 2:
            for c in range(nz[-1] + 1, w):
                out[r][c] = 1
    return out

